// seed: tests/seed.admin.spec.ts (admin, с #359741; было: гость) · прод, только чтение. Тикет #dc52b7 («מה רצוי»: «הכתוביות קריאות במלואן גם כשהפקדים מוצגים»).
// Как измеряется (так же, как при ручной проверке 2026-11-04):
//  - плашка субтитра — тёмный блок с оранжевой полосой у правого края (x 90,4–98 % ширины кадра); её низ ищется
//    в самом кадре видео (canvas, исходные 720×1558) и переводится в px плеера (масштаб = высота плеера / 1558 ≈ 0,361);
//  - значки пульта — строки снимка плеера (пульт показан: пауза + курсор над видео), где пиксель светлый (>200),
//    а в том же месте кадра без пульта тёмный (<140), ниже 85 % высоты.
// Принято: плеер 260×563 на 375 и 1440; низ плашки ≈ 483 px; значки пульта ≥ 508 px; зазор ≥ 25 px.
// Второй блок (specs 1.9, кейсы GUIDES-14…16, #4abcf4): кнопки, о которых в этот момент говорит диктор, видны —
// плашка субтитра их не закрывает (ни в кадре, ни на снимке плеера с показанным пультом).
import { test, expect, Page } from '@playwright/test';
import { prepareReadOnly, GUIDES, LOAD, openGuides, videoOf, startDesktop, expectPlaying, Guide } from './guides.helpers';

// #359741: /guides видит только админ (гость и user уходят на /) — сессия admin, файл сессии не перезаписывается.
test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

/** Моменты с субтитром (с), из ручной проверки 2026-11-04 (2- и 3-строчные, в начале и в конце ролика).
 *  home/area — по файлам PR #196 (приёмка #4abcf4), publish — PR #199 (приёмка #04a6d8, кадры 2026-11-05): плашка есть во всех моментах, низ ≈ 483. */
const MOMENTS: Record<Guide['id'], number[]> = {
  home: [7.5, 44.5, 97.5],
  signup: [8, 39, 67.5, 70],
  publish: [13, 70, 74, 124], // версия PR #199 (126,37 с, #04a6d8): 63 теперь пауза между субтитрами; 27,7–49,4 и 51,8–61,4 плашка наверху — не у пульта
  search: [12, 50, 114],
  area: [7, 9.5, 118.5],
};
const PLAYER = { width: 260, height: 563, tol: 2 };
const SOURCE = { width: 720, height: 1558 };
const MAX_PLATE_BOTTOM = 490; // принято ≈ 483 px от верха плеера
const MIN_GAP = 15; // принято 25 px между низом плашки и значками пульта

type Measure = { plateTop: number | null; plateBottom: number | null; iconTop: number | null };

/** Низ плашки по кадру + верх значков пульта по снимку плеера, в CSS px плеера. */
async function measure(page: Page, g: Guide): Promise<Measure> {
  const video = videoOf(page, g);
  const box = (await video.boundingBox())!;
  // Показать пульт: курсор над видео (на паузе пульт не прячется).
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.mouse.move(box.x + box.width / 2 + 3, box.y + box.height / 2 + 3);
  await video.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
  const shot = (await video.screenshot({ scale: 'css' })).toString('base64');
  return video.evaluate(async (v: HTMLVideoElement, shot: string) => {
    const W = v.videoWidth, H = v.videoHeight;
    const c = document.createElement('canvas');
    c.width = W; c.height = H;
    const g = c.getContext('2d')!;
    g.drawImage(v, 0, 0, W, H);
    const d = g.getImageData(0, 0, W, H).data;
    const x0 = Math.round(W * 0.904), x1 = Math.round(W * 0.98);
    let best: { a: number; b: number } | null = null, cur: { a: number; b: number } | null = null;
    for (let y = Math.floor(H * 0.45); y < H; y++) {
      let n = 0;
      for (let x = x0; x < x1; x++) {
        const i = (y * W + x) * 4;
        if (d[i] > 200 && d[i + 1] > 80 && d[i + 1] < 175 && d[i + 2] < 90) n++;
      }
      if (n >= 3) {
        if (cur && y - cur.b <= 3) cur.b = y;
        else { if (cur && (!best || cur.b - cur.a > best.b - best.a)) best = cur; cur = { a: y, b: y }; }
      }
    }
    if (cur && (!best || cur.b - cur.a > best.b - best.a)) best = cur;
    if (best && best.b - best.a < 150) best = null; // плашка 2–3 строки ≈ 185–235 px исходника
    const k = v.getBoundingClientRect().height / H;

    const img = new Image();
    img.src = 'data:image/png;base64,' + shot;
    await img.decode();
    const w = img.width, h = img.height;
    const cs = document.createElement('canvas'); cs.width = w; cs.height = h;
    const gs = cs.getContext('2d')!; gs.drawImage(img, 0, 0);
    const s = gs.getImageData(0, 0, w, h).data;
    const cf = document.createElement('canvas'); cf.width = w; cf.height = h;
    const gf = cf.getContext('2d')!; gf.drawImage(v, 0, 0, w, h);
    const f = gf.getImageData(0, 0, w, h).data;
    const gray = (a: Uint8ClampedArray, i: number) => (a[i] + a[i + 1] + a[i + 2]) / 3;
    let iconTop: number | null = null;
    for (let y = Math.floor(h * 0.85); y < h && iconTop === null; y++) {
      let n = 0;
      for (let x = 0; x < w; x++) { const i = (y * w + x) * 4; if (gray(s, i) > 200 && gray(f, i) < 140) n++; }
      if (n >= 4) iconTop = y;
    }
    return {
      plateTop: best ? best.a * k : null,
      plateBottom: best ? (best.b + 1) * k : null,
      iconTop,
    };
  }, shot);
}

async function seek(page: Page, g: Guide, t: number) {
  await videoOf(page, g).evaluate(
    (v: HTMLVideoElement, t: number) => new Promise((r) => { v.addEventListener('seeked', r, { once: true }); v.currentTime = t; }),
    t,
  );
}

function suite(tag: '@desktop' | '@android', label: string) {
  for (const g of GUIDES) {
    test(`${g.id}: субтитры над пультом плеера, ${label} #dc52b7 ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (b) => b.click());
      await openGuides(page);
      const video = videoOf(page, g);

      const box = (await video.boundingBox())!;
      expect(Math.abs(box.width - PLAYER.width), `${g.id}: ширина плеера ${box.width}`).toBeLessThanOrEqual(PLAYER.tol);
      expect(Math.abs(box.height - PLAYER.height), `${g.id}: высота плеера ${box.height}`).toBeLessThanOrEqual(PLAYER.tol);

      // Запуск пользователем (фокус + «Пробел»), затем пауза — пульт показан, кадр стоит.
      await startDesktop(page, video);
      await expectPlaying(video, 0.3, g.id);
      await video.evaluate((v: HTMLVideoElement) => v.pause());
      const size = await video.evaluate((v: HTMLVideoElement) => ({ w: v.videoWidth, h: v.videoHeight, fit: getComputedStyle(v).objectFit }));
      expect(size, `${g.id}: исходный кадр и вписывание`).toEqual({ w: SOURCE.width, h: SOURCE.height, fit: 'contain' });

      let iconsSeen = 0;
      for (const t of MOMENTS[g.id]) {
        await seek(page, g, t);
        const m = await measure(page, g);
        const at = `${g.id} ${t} с`;
        expect(m.plateBottom, `${at}: на кадре есть плашка субтитра (D-08)`).not.toBeNull();
        expect(m.plateBottom!, `${at}: низ плашки ${m.plateBottom?.toFixed(1)} px (принято ≈ 483)`).toBeLessThanOrEqual(MAX_PLATE_BOTTOM);
        if (m.iconTop !== null) {
          iconsSeen++;
          expect(m.iconTop - m.plateBottom!, `${at}: зазор плашка → значки пульта (значки ${m.iconTop} px)`).toBeGreaterThanOrEqual(MIN_GAP);
        }
      }
      expect(iconsSeen, `${g.id}: пульт найден на снимках хотя бы в одном моменте (иначе проверка зазора пустая)`).toBeGreaterThan(0);
    });
  }
}

test.describe('Видео-инструкции /guides — субтитры не закрыты пультом, десктоп 1440', () => {
  suite('@desktop', 'десктоп 1440');
});

