// ─── #4abcf4: кнопки, о которых говорит диктор, видны над/под плашкой субтитра (specs 1.9, GUIDES-14…16) ───

/** Ряд кнопки в исходном кадре 720×1558 (px от верха) и её цвет — замер принятой версии 2026-11-04 (PR #196). */
type Band = { label: string; top: number; bottom: number; kind: 'green' | 'orange' | 'dark' };
type Moment = { t: number; subtitle: boolean };

const SPOKEN: { case: string; id: Guide['id']; what: string; bands: Band[]; moments: Moment[]; minGap: number }[] = [
  {
    case: 'GUIDES-14', id: 'home', what: '0:41–0:47 «WhatsApp, הצגת טלפון או השארת פרטים»',
    bands: [
      { label: 'WhatsApp', top: 586, bottom: 666, kind: 'green' },
      { label: 'הצגת טלפון / השארת פרטים', top: 682, bottom: 761, kind: 'orange' },
    ],
    moments: [41, 42.5, 44, 45.5, 47].map((t) => ({ t, subtitle: true })), // принято: плашка ниже кнопок, зазор ≈ 123 px
    minGap: 0,
  },
  {
    case: 'GUIDES-15', id: 'home', what: '1:19–1:24 «התחברות» → кнопка «התחבר»',
    bands: [{ label: 'התחבר', top: 1208, bottom: 1295, kind: 'dark' }],
    // 1:19–1:20 субтитра нет; с 1:20,5 он наверху экрана (≈ 49–116 px), до кнопки ≈ 321 px
    moments: [{ t: 79.5, subtitle: false }, ...[81, 82.5, 84].map((t) => ({ t, subtitle: true }))],
    minGap: 0,
  },
  {
    case: 'GUIDES-16', id: 'area', what: '1:59–2:02 «ומכאן גם מפרסמים עסק חדש למכירה»',
    bands: [{ label: 'פרסום עסק למכירה', top: 702, bottom: 781, kind: 'orange' }],
    moments: [119.6, 120.5, 121.5, 122].map((t) => ({ t, subtitle: true })), // принято: зазор ≈ 134 px
    minGap: 0,
  },
];

type ButtonMeasure = {
  k: number;
  plate: { top: number; bottom: number } | null; // px плеера
  frame: number[]; // доля строк ряда кнопки, где виден её цвет — кадр видео (пульт не влияет)
  shot: number[]; // то же на снимке плеера с показанным пультом
};

/** Плашка субтитра (по всей высоте кадра — бывает и наверху) и присутствие каждой кнопки в кадре и на снимке с пультом. */
async function measureButtons(page: Page, g: Guide, bands: Band[]): Promise<ButtonMeasure> {
  const video = videoOf(page, g);
  const box = (await video.boundingBox())!;
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.mouse.move(box.x + box.width / 2 + 3, box.y + box.height / 2 + 3);
  await video.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
  const shot = (await video.screenshot({ scale: 'css' })).toString('base64');
  return video.evaluate(async (v: HTMLVideoElement, [shot, bands]: [string, Band[]]) => {
    const W = v.videoWidth, H = v.videoHeight;
    const c = document.createElement('canvas'); c.width = W; c.height = H;
    const g = c.getContext('2d')!; g.drawImage(v, 0, 0, W, H);
    const d = g.getImageData(0, 0, W, H).data;
    // Плашка: тёмный блок с оранжевой полосой у правого края (x 90,4–98 %), самая длинная серия строк ≥ 150 px.
    const x0 = Math.round(W * 0.904), x1 = Math.round(W * 0.98);
    let best: { a: number; b: number } | null = null, cur: { a: number; b: number } | null = null;
    for (let y = 0; y < H; y++) {
      let n = 0;
      for (let x = x0; x < x1; x++) { const i = (y * W + x) * 4; if (d[i] > 200 && d[i + 1] > 80 && d[i + 1] < 175 && d[i + 2] < 90) n++; }
      if (n >= 3) {
        if (cur && y - cur.b <= 3) cur.b = y;
        else { if (cur && (!best || cur.b - cur.a > best.b - best.a)) best = cur; cur = { a: y, b: y }; }
      }
    }
    if (cur && (!best || cur.b - cur.a > best.b - best.a)) best = cur;
    if (best && best.b - best.a < 150) best = null;
    const k = v.getBoundingClientRect().height / H;

    const match = (kind: Band['kind'], r: number, gg: number, b: number) =>
      kind === 'green' ? r < 120 && gg > 150 && b < 140
        : kind === 'orange' ? r > 200 && gg > 80 && gg < 160 && b < 90
          : r < 70 && gg < 70 && b < 70;
    const need = { green: 0.08, orange: 0.15, dark: 0.6 } as const; // доля ширины строки цвета кнопки
    const share = (px: Uint8ClampedArray, w: number, top: number, bottom: number, kind: Band['kind']) => {
      let ok = 0;
      for (let y = top; y <= bottom; y++) {
        let n = 0;
        for (let x = 0; x < w; x += 2) { const i = (y * w + x) * 4; if (match(kind, px[i], px[i + 1], px[i + 2])) n++; }
        if (n / (w / 2) > need[kind]) ok++;
      }
      return ok / (bottom - top + 1);
    };

    const img = new Image(); img.src = 'data:image/png;base64,' + shot; await img.decode();
    const sc = document.createElement('canvas'); sc.width = img.width; sc.height = img.height;
    const sg = sc.getContext('2d')!; sg.drawImage(img, 0, 0);
    const s = sg.getImageData(0, 0, img.width, img.height).data;
    const ky = img.height / H; // снимок в CSS px плеера
    return {
      k,
      plate: best ? { top: best.a * k, bottom: (best.b + 1) * k } : null,
      frame: bands.map((b) => share(d, W, b.top, b.bottom, b.kind)),
      // на снимке ряд берётся с отступом 2 px внутрь — края кнопки размыты масштабированием
      shot: bands.map((b) => share(s, img.width, Math.ceil(b.top * ky) + 2, Math.floor((b.bottom + 1) * ky) - 2, b.kind)),
    };
  }, [shot, bands] as [string, Band[]]);
}

function spokenSuite(tag: '@desktop' | '@android', label: string) {
  for (const sp of SPOKEN) {
    const g = GUIDES.find((x) => x.id === sp.id)!;
    test(`${sp.id} ${sp.what}: кнопки, о которых говорит диктор, не закрыты субтитром, ${label} #4abcf4 ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (b) => b.click());
      await openGuides(page);
      const video = videoOf(page, g);
      const box = (await video.boundingBox())!;
      expect(Math.abs(box.height - PLAYER.height), `${g.id}: высота плеера ${box.height}`).toBeLessThanOrEqual(PLAYER.tol);

      await startDesktop(page, video);
      await expectPlaying(video, 0.3, g.id);
      await video.evaluate((v: HTMLVideoElement) => v.pause());
      const size = await video.evaluate((v: HTMLVideoElement) => ({ w: v.videoWidth, h: v.videoHeight }));
      expect(size, `${g.id}: исходный кадр`).toEqual({ w: SOURCE.width, h: SOURCE.height });

      for (const m of sp.moments) {
        await seek(page, g, m.t);
        const r = await measureButtons(page, g, sp.bands);
        const at = `${sp.case} ${g.id} ${m.t} с`;
        sp.bands.forEach((b, i) => {
          expect(r.frame[i], `${at}: «${b.label}» в кадре (ряд ${b.top}–${b.bottom} px исходника)`).toBeGreaterThanOrEqual(0.9);
          expect(r.shot[i], `${at}: «${b.label}» видна на плеере с показанным пультом`).toBeGreaterThanOrEqual(0.9);
        });
        if (m.subtitle) expect(r.plate, `${at}: на кадре есть плашка субтитра (диктор говорит)`).not.toBeNull();
        if (r.plate) {
          for (const b of sp.bands) {
            const top = b.top * r.k, bottom = (b.bottom + 1) * r.k;
            const gap = r.plate.top >= bottom ? r.plate.top - bottom : top - r.plate.bottom;
            expect(gap, `${at}: плашка ${r.plate.top.toFixed(1)}–${r.plate.bottom.toFixed(1)} px не закрывает «${b.label}» ${top.toFixed(1)}–${bottom.toFixed(1)} px`)
              .toBeGreaterThanOrEqual(sp.minGap);
          }
        }
      }
    });
  }
}

